import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import axiosInstance from '../axiosConfig';
import Sidebar from '../components/Sidebar';

// STS-12: View Joined Tournaments — Participant's dashboard, styled after the
// GameDay Figma design (dark theme + sidebar).
const ParticipantDashboard = () => {
  const { user } = useAuth();
  const [tournaments, setTournaments] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchJoined = async () => {
      try {
        const response = await axiosInstance.get('/api/tournaments/joined/list', {
          headers: { Authorization: `Bearer ${user.token}` },
        });
        setTournaments(response.data);
      } catch (error) {
        alert('Failed to load your joined tournaments.');
      } finally {
        setLoading(false);
      }
    };

    if (user) fetchJoined();
  }, [user]);

  const navItems = [{ to: '/', label: 'Discover Tournaments' }];

  return (
    <Sidebar title="Participant" navItems={navItems}>
      <h1 className="text-3xl font-black text-white uppercase mb-1">Dashboard</h1>
      <p className="text-[#94a3b8] text-sm mb-6">Tournaments you've registered for.</p>

      {loading ? (
        <p className="text-[#94a3b8]">Loading...</p>
      ) : tournaments.length === 0 ? (
        <p className="text-[#94a3b8]">
          You haven't joined any tournaments yet.{' '}
          <Link to="/" className="text-[#cf0] underline">
            Discover tournaments
          </Link>{' '}
          to get started.
        </p>
      ) : (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {tournaments.map((t) => (
            <Link
              to={`/tournaments/${t._id}`}
              key={t._id}
              className="bg-[#171e2c] border border-[#2a3547] p-4 rounded-2xl hover:border-[#cf0] transition"
            >
              <span className="bg-[#232d3f] border border-[#2a3547] text-white text-[10px] font-bold uppercase px-2 py-1 rounded-md">
                {t.sport}
              </span>
              <h2 className="font-bold text-white text-lg mt-2">{t.name}</h2>
              <p className="text-sm text-[#94a3b8]">
                {new Date(t.date).toLocaleDateString()}
              </p>
              <p className="text-sm text-white mt-1">
                Organized by {t.organizerId?.name || 'Unknown'} &middot; {t.status}
              </p>
            </Link>
          ))}
        </div>
      )}
    </Sidebar>
  );
};

export default ParticipantDashboard;
